"""Self-contained latest case report, with historical views kept explicitly separate."""
from pathlib import Path
import sys,json,base64,io,html
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];run=sys.argv[1];R=ROOT/'runs'/run;D=ROOT/'review/previews'/run;OUT=Path(sys.argv[2]);OUT.parent.mkdir(parents=True,exist_ok=True)
sp=json.loads((R/'spec.json').read_text());qa=json.loads((R/'audit.json').read_text());wc=json.loads((R/'world_check.json').read_text());rc=json.loads((R/'random_check.json').read_text());records=json.loads((D/'render_report.json').read_text());css=(ROOT/'assets/report.css').read_text();images={};used=set()
def readimage(key,p,expected=None):
 im=Image.open(p)
 if expected:assert im.info['source_nbt_sha256']==expected
 buf=io.BytesIO();im.convert('RGB').save(buf,format='WEBP',quality=88,method=6);images[key]='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
for rec in records:readimage(Path(rec['image']).stem,D/rec['image'],sp['source_nbt_sha256'])
images['exploded']='data:image/svg+xml;base64,'+base64.b64encode((D/'exploded.svg').read_bytes()).decode()
for old in ['exterior_SE','front_eye','elevation_south','top']:
 readimage('before_'+old,ROOT/'review/previews/M06'/f'{old}.png','234c566d32af2661910d49dc43ca36ea37f8a14734d2fec00cfdd25f0dc67b14')
for old in ['plan_1','entry_eye','kitchen_eye']:readimage('M03_'+old,ROOT/'review/previews/M03'/f'{old}.png')
readimage('M04_understair',ROOT/'review/previews/M04/understair_eye.png')
def img(key,alt='',elid=''):
 used.add(key);return '<img class="zoom" '+(f'id="{elid}" 'if elid else'')+f'data-img="{key}" src="{images[key]}" alt="{html.escape(alt or key)}" loading="lazy">'
def card(key,title,caption):return '<figure>'+img(key,title)+f'<figcaption><strong>{title}</strong><span>{caption}</span></figcaption></figure>'
def row(a,b,c=''):return '<tr>'+''.join('<td>'+v+'</td>'for v in ([a,b,c]if c else[a,b]))+'</tr>'
def download(p,mime,label):return f'<a class="download" download="{p.name}" href="data:{mime};base64,{base64.b64encode(p.read_bytes()).decode()}">{label} ↗</a>'
def section(id,k,title,body):return f'<section id="{id}"><div class="kicker">{k}</div><h2>{title}</h2>{body}</section>'
def controls(id,attr,views):return f'<div class="controls" id="{id}">'+''.join(f'<button data-{attr}="{key}" class="'+('active'if i==0 else'')+f'">{title}</button>'for i,(key,title)in enumerate(views))+'</div>'
p=['<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>日和小食 · 门面与屋顶返工</title><style>'+css+'table{table-layout:fixed}td{overflow-wrap:anywhere}.hero-frame img{object-fit:contain!important}nav{flex-wrap:wrap}</style></head><body><header><b>HIYORI / 08 <span class="stamp">日和</span></b><nav><a href="#front">店口</a><a href="#roof">屋顶</a><a href="#inside">内饰</a><a href="#sources">研究</a><a href="#delivery">存档</a></nav></header><main>']
p.append('<section class="hero"><div class="intro"><div><div class="kicker">Machiya08 / '+run+' / HAF 0.4</div><h1>让小店，<br>向街道打开。</h1><span class="tag">街边门面返工</span><span class="tag">主次屋顶</span><span class="tag">二层住商小楼</span></div><div><p class="lead">打开原先的小窗与封闭入口，让街边能看见客席、柜面和暖灯；上层窗组、檐口和屋顶分别组织主次。</p><p class="small">以 Freedom 的公开展示图及本次复看的沿街商铺片段作参考。小山墙和具体平面属于本项目原创改法。</p></div></div><div class="hero-frame">'+img('front_eye','新版临街店口','hero-img')+'<div class="label" id="hero-label">新版街边眼高 · 最终 NBT 离线预览</div></div>'+controls('hero-controls','view',[('front_eye','新版店口'),('before_front_eye','旧版店口'),('exterior_SE','新版整栋'),('before_exterior_SE','旧版整栋'),('roof_oblique','屋顶近景'),('night_SE','夜景'),('street_corner','沿街转角')])+'<div class="stats"><div><strong>3 段</strong><span>窗台 / 退入入口 / 临街客席</span></div><div><strong>2 层</strong><span>首层居酒屋 · 上层住家</span></div><div><strong>11 席</strong><span>既有客席组保留</span></div><div><strong>'+str(len(records))+' 图</strong><span>另附 8 张历史对照</span></div></div><div class="note">这版呈现营业中的开放店口：原单扇正门已移除，入口为三格宽开口，未实现打烊闭合机制。其余七樘门保留。预览来自实际建筑文件，尚未进行 Minecraft 客户端验收。</div></section>')
p.append(section('diagnosis','01 / Diagnosis','原先的死板，来自空间关系。','<table><tr><th>旧版问题</th><th>本版改变</th></tr>'+row('首层和楼上共用小窗逻辑','首层按营业功能开口，上层保留居住隐私；卫浴不跟着打开。')+row('门、窗、墙都挤在一个平面','入口后退一格，窗台向前伸，薄格扇停在柱侧；从街道看见房间深处。')+row('长檐等深、瓦面一整片','店檐按窗台与入口分段，主坡面加一个较小前向山墙，补屋脊、山墙木作和檐端。')+row('道具摆了，却没有门面层次','红色候位凳、低盆与高盆聚在一侧，菜单挂柱，入口中间留空。')+'</table>'))
p.append(section('sources','02 / Sources & interpretation','这次具体看了什么。','<p><a href="https://www.youtube.com/watch?v=KLR765Njya0">Freedom · Japanese Yakitori Tavern #80</a>：已核对作者与标题，视频画面未成功加载。实际查看的是带 Freedom 水印的<a href="https://in.pinterest.com/pin/minecraft-yakitori-tavern-tutorial--658088564314845518/">公开展示静帧</a>，无可确认时间戳。</p><p><a href="https://www.bilibili.com/video/BV1aG4y1B7fo/">Freedom · 沿街转角商铺 #104（转载）</a>：本次新查看 <b>00:12、00:25</b> 的展示画面；原视频 <a href="https://www.youtube.com/watch?v=I40jEm-xIsU">I40jEm-xIsU</a>。这是片段抽查，不是完整观看。</p><table><tr><th>实际可见</th><th>本项目采用</th><th>边界</th></tr>'+row('#80：街边开口里能看见低柜台，入口与柜台并置','左侧开窗接低窗台，中段入口，侧向短台面','不推断其完整后厨或逐块配方')+row('#104 00:25：柱、暖帘、陈列与后景前后分层','保留柱和局部遮挡，扩大通视，把入口后退','参考深度关系，未复制原店布局')+row('#104 00:12：上下檐分层，上层另有窗外构件','窗组长短、薄格扇、局部花台及檐下灯','花台为装饰窗沿，不是可走阳台')+row('两份画面都有主屋面与店前小檐','主次屋顶、短长檐、收边与木构端头','新增前向小山墙是原创设计选择，非视频观察结论')+'</table><p class="small">此前 #101、#104 的记录继续保留在工程 input/JapanDetail01_record.json。本次只保存观察与来源记录，不打包第三方截图或视频，不宣称训练模型权重。</p>'))
p.append(section('front','03 / Street frontage','街边能看到，店里有人活动的地方。','<div class="grid">'+card('before_front_eye','M06 · 旧门面','单扇门、小窗和厚窗下墙，店内被遮住。')+card('front_eye',run+' · 营业门面','相同机位；三格入口、窗台与餐位开口，让视线进入室内。')+card('street_window','站在左侧窗台前','可见既有卡座、壁架、墙画和灯；它是陈列与临街窗台，不另外占掉室内就餐组。')+card('frontage_inside','从店内望向街道','保留完整顶棚，看门口、窗台和人行道的连续关系。')+card('street_corner','沿街转角','侧面短开口、红色帘面、柱边菜单与单盆，角部仍保留木柱。')+card('storefront_section','门面局部正交裁切','仅显示 z=20…26、y&lt;12 的前沿范围，用于核对前后层次；不是完整平面。')+'</div>'))
