p.append(section('roof','05 / Roof hierarchy','主坡面之外，只加一个次要重心。','<div class="grid">'+card('before_exterior_SE','M06 · 原整栋','等深长檐和大块连续瓦面主导轮廓。')+card('exterior_SE',run+' · 新整栋','相同相机；小前山墙靠东侧，窗沿与首层屋檐分开。')+card('roof_oblique','屋面交接与山墙近景','主屋脊、边瓦和小山墙形成层级；不是多层重檐塔式屋顶。')+card('eave_detail','檐底与端头','同一建筑的木梁、椽端与薄边层次。')+'</div><details><summary>俯视对照与其他方向</summary><div class="grid">'+card('before_top','M06 · 原屋顶俯视','垂直正交，非倾斜鸟瞰。')+card('top',run+' · 当前屋顶俯视','同机位，可检查前向小山墙的范围。')+''.join(card('exterior_'+k,t+'斜视','四个45°方向共用比例与目标点。')for k,t in [('SW','西南'),('NW','西北'),('NE','东北')])+card('elevation_north','北立面','后庭一侧保留较安静的窗墙关系。')+card('elevation_west','西立面','楼梯与私密侧保持较完整墙面。')+'</div></details>'))
