p.append(section('delivery','10 / Into Minecraft','带进地图，再看一次街边。','<p><a class="download" href="'+worldurl+'">地图包 ↗</a><a class="download" href="'+projecturl+'">工程包 ↗</a></p><ol><li>解压 <b>Machiya08_World_1.21.1.zip</b>，把 <code>Machiya08_1.21.1</code> 放进 <code>saves</code>。</li><li>使用 Java 1.21.1、创造模式、无必需模组。出生点 <code>-1 65 9</code> 朝北。</li><li>先看门口左窗台 → 退入入口 → 东侧街边 → 屋顶，再进屋复核家具和楼梯。</li></ol><div class="controls">'+download(R/'Machiya08.nbt','application/octet-stream','下载 NBT')+download(R/'design_contract.json','application/json','空间与门面数据')+download(R/'design_prompts.txt','text/plain','设计关键词')+download(ROOT/'input/Freedom_frontage_research.json','application/json','研究记录')+'</div><table><tr><th>检查</th><th>本版结果与边界</th></tr>'+row('结构与世界',f'{wc["checked_cells"]:,} 格回读；0 差异；{sp["block_entities"]} 个方块实体和 3 幅画实体。')+row('通行与楼梯',f'{len(sp["doors"])} 樘门配对、{len(sp["use_points"])} 个使用点、91 个楼梯采样通过。门视作打开，使用近似碰撞盒。')+row('局部保护','保留楼梯、楼梯下和室内家具组；只改外壳、屋顶、临街构件及入口交界。详见工程差分报告。')+row('预览',f'{len(records)} 张当前图均绑定最终 NBT 哈希；8 张旧图明确标注版本。')+row('未完成','Minecraft 客户端碰撞、交互、实际照明与新版审美验收。')+'</table><details><summary>表现边界与同源记录</summary><p>静态原版模型和纹理离线渲染，不是 Minecraft 截图。床、旗帜、告示牌外形近似，告示牌文字已写入世界但预览未完整显示；动态纹理、植物染色和光照不完整。座位、沙发、杯瓶和布巾为装饰，木桶内为空。</p><p>上层窗沿不是可进入阳台；阁楼小山墙与百叶仅作屋面造型，没有另做可进入阁楼。原版素材不随工程包分发，附官方校验下载方法。</p><p>最终 NBT SHA-256：<code>'+sp['source_nbt_sha256']+'</code></p></details>'))
