script='''const images=IMAGES;const viewer=document.getElementById('viewer');function setImage(id,key){const x=document.getElementById(id);x.src=images[key];x.dataset.img=key;}function active(id,b){document.querySelectorAll('#'+id+' button').forEach(x=>x.classList.toggle('active',x===b));}document.getElementById('hero-controls').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(!b)return;active('hero-controls',b);setImage('hero-img',b.dataset.view);document.getElementById('hero-label').textContent=b.textContent+' · NBT 离线模型预览';});document.getElementById('room-controls').addEventListener('click',e=>{const b=e.target.closest('button[data-room]');if(!b)return;active('room-controls',b);setImage('room-img',b.dataset.room);document.getElementById('room-title').textContent=b.textContent+' · 完整顶棚人物视角';});document.getElementById('plan-controls').addEventListener('click',e=>{const b=e.target.closest('button[data-plan]');if(!b)return;active('plan-controls',b);setImage('plan-img',b.dataset.plan);document.getElementById('plan-title').textContent=b.dataset.plan==='plan_1'?'一层 · 客席 / 后厨 / 卫浴 / 楼梯':'二层 · 卧室 / 茶席 / 书桌';});document.addEventListener('click',e=>{if(!e.target.matches('img.zoom'))return;const x=document.getElementById('viewer-img');x.src=images[e.target.dataset.img];x.alt=e.target.alt;viewer.showModal();});document.getElementById('close-viewer').addEventListener('click',()=>viewer.close());'''
script=script.replace('IMAGES','Object.assign(Object.fromEntries(Array.from(document.querySelectorAll("img[data-img]")).map(el=>[el.dataset.img,el.src])), '+json.dumps({k:v for k,v in images.items()if k not in used})+')');p.append('<script>'+script+'</script></body></html>')
